# German texts for the Act III and Act IV clan story and the Solenne reckoning (story34).
# Source: data/dialogue/clans.json, data/scenes/solenne_reckoning.json, data/story_battles.json.
KEEP = ["Liss", "Kerr Haldane", "Tobs", "Ottilie", "Fenrick", "Mother Grell", "Sable", "Wren", "Pip", "Marlo", "Vash", "Brannoc"]
T = {
"Sable: Old friend! You look terrible. Ashmere suits you.": "Sable: Alter Freund! Du siehst furchtbar aus. Ashmere steht dir.",
"Sable: There's a card hall under the basalt. Friends only. Small stakes, big snacks.": "Sable: Unter dem Basalt gibt es einen Kartensaal. Nur für Freunde. Kleine Einsätze, große Snacks.",
"Sable: Bring your strongest Spirling. Card halls get rowdy. Somebody always flips a table.": "Sable: Bring deinen stärksten Spirling mit. In Kartensälen wird es laut. Irgendwer wirft immer einen Tisch um.",
"Can I bring a friend?": "Darf ich wen mitbringen?",
"Sable: A friend? Bring two. The more the merrier. The more the cheaper per head.": "Sable: Einen Freund? Bring zwei. Je mehr, desto lustiger. Je mehr, desto billiger pro Kopf.",
"Sable: ...That came out wrong. It's the ash. Makes a man honest at the worst moments.": "Sable: ...Das kam falsch raus. Das ist die Asche. Sie macht einen ehrlich, immer im falschen Moment.",
"Sable: No hard feelings? I've got some soft ones. Cheap. For you.": "Sable: Keine bösen Gefühle? Ich hätte noch ein paar weiche. Billig. Für dich.",
"Under the basalt there are no cards. Only Marrovel's enemies, a price list, and your name on it.": "Unter dem Basalt gibt es keine Karten. Nur Marrovels Feinde, eine Preisliste und deinen Namen darauf.",
"Sable: I said friends only. They're my friends. You're the snacks.": "Sable: Ich sagte, nur für Freunde. Das sind meine Freunde. Du bist die Snacks.",
"Sable: Don't look at me like that. I gave you a discount. Forty percent. That's practically love.": "Sable: Schau mich nicht so an. Ich habe dir Rabatt gegeben. Vierzig Prozent. Das ist praktisch Liebe.",
"You come in through the coal chute, behind the ambush. Six hands turn round at once.": "Du kommst durch die Kohlenrutsche, hinter dem Hinterhalt. Sechs Handlanger drehen sich gleichzeitig um.",
"Sable: For the record, I was going to warn you. Right after they paid. Timing is everything.": "Sable: Fürs Protokoll: Ich wollte dich warnen. Gleich nachdem sie bezahlt hätten. Timing ist alles.",
"Marlo: They asked me to swear on my mother's name. I said she charges extra.": "Marlo: Sie wollten, dass ich auf den Namen meiner Mutter schwöre. Ich sagte, das kostet extra.",
"On the counter: a bill for your last three alibis. Marked 'paid in full'.": "Auf dem Tresen: eine Rechnung für deine letzten drei Alibis. Vermerk: 'vollständig bezahlt'.",
"Mother Grell: I wore black for a month. Black is slimming. Everybody won.": "Mother Grell: Ich habe einen Monat Schwarz getragen. Schwarz macht schlank. Alle haben gewonnen.",
"Mother Grell: Now you know. Knowing is expensive, dear. Who are you going to sell it to?": "Mother Grell: Jetzt weißt du es. Wissen ist teuer, Schätzchen. An wen verkaufst du es?",
"Keep your secret": "Dein Geheimnis bleibt bei mir",
"Tell the Marrovels": "Den Marrovels erzählen",
"Brannoc: Thirty years I was the heir. Turns out I was the wrapping paper.": "Brannoc: Dreißig Jahre war ich der Erbe. Dabei war ich nur das Geschenkpapier.",
"Brannoc: The Ruskwebers offered me work. Fixed hours. No family dinners. I said yes before they finished.": "Brannoc: Die Ruskweber haben mir Arbeit angeboten. Feste Zeiten. Keine Familienessen. Ich sagte ja, bevor sie fertig waren.",
"Lejla: Fenrick's new daughter, Liss? She has me copy her letters. All addressed to Sable. Lovely hand.": "Lejla: Fenricks neue Tochter, Liss? Ich soll ihre Briefe abschreiben. Alle an Sable adressiert. Schöne Handschrift.",
"Fenrick: Also, I have a daughter. Liss. From Ashmere. Long story. Short evening.": "Fenrick: Außerdem habe ich eine Tochter. Liss. Aus Ashmere. Lange Geschichte. Kurzer Abend.",
"Fenrick: Ottilie gave her a room by the stairs. Ottilie always gives people rooms by the stairs.": "Fenrick: Ottilie hat ihr ein Zimmer an der Treppe gegeben. Ottilie gibt Leuten immer Zimmer an der Treppe.",
"Welcome her": "Sie willkommen heißen",
"Watch her first": "Sie erst beobachten",
"At the family dinner Liss passes you the salt, and a folded note under the table. You keep both.": "Beim Familienessen reicht Liss dir das Salz und unter dem Tisch einen gefalteten Zettel. Du behältst beides.",
"The note is for Sable. It lists every word said at the council. Including 'pass the salt'.": "Der Zettel ist für Sable. Darauf steht jedes Wort aus der Ratssitzung. Auch 'reich mir das Salz'.",
"Liss: ...Fine. Sable pays me. Fenrick only pays attention. Which would you pick?": "Liss: ...Schön. Sable bezahlt mich. Fenrick schenkt mir nur Aufmerksamkeit. Was würdest du nehmen?",
"From now on she writes what you tell her. Fenrick never forgives you for knowing first.": "Ab jetzt schreibt sie, was du ihr diktierst. Fenrick verzeiht dir nie, dass du es zuerst wusstest.",
"Liss smiles all through dinner. By dessert Sable knows the Marrovel convoy route.": "Liss lächelt das ganze Essen lang. Beim Nachtisch kennt Sable die Route des Marrovel-Konvois.",
"Liss: Welcome to the family. The food taster sits on the left. I sit wherever the money is.": "Liss: Willkommen in der Familie. Der Vorkoster sitzt links. Ich sitze, wo das Geld ist.",
"On the road out of town, Ruskweber hands are waiting. They brought a map. Yours.": "Auf der Straße aus der Stadt warten Ruskweber-Handlanger. Sie haben eine Karte dabei. Deine.",
"Fenrick: Do you hear them? My old Spirlings. They want their supper. They've been gone for years. Still hungry.": "Fenrick: Hörst du sie? Meine alten Spirlinge. Sie wollen ihr Abendessen. Seit Jahren fort. Immer noch hungrig.",
"Fenrick's bond Spirling turns its head towards you. Its eyes are somewhere else. Some other century.": "Fenricks Bindungsspirling dreht den Kopf zu dir. Seine Augen sind woanders. In einem anderen Jahrhundert.",
"Fenrick: He's not wicked. He just mixes up the centuries. So do I, after lunch.": "Fenrick: Er ist nicht böse. Er verwechselt nur die Jahrhunderte. Ich auch, nach dem Mittagessen.",
"Marlo is already there, sleeve rolled up, sleeping draught in hand.": "Marlo ist schon da, Ärmel hochgekrempelt, den Schlaftrunk in der Hand.",
"Marlo: Big lad. Little sip. Sleep it off, both of you.": "Marlo: Großer Junge. Kleiner Schluck. Schlaft es aus, alle beide.",
"Fenrick: I will remember this humiliation. ...What was I remembering?": "Fenrick: Diese Demütigung merke ich mir. ...Was wollte ich mir merken?",
"Nobody comes. You run. The Spirling runs faster, and snatches your lead Spirling's keepsake as a trophy.": "Niemand kommt. Du rennst. Der Spirling rennt schneller und schnappt sich das Andenken deines Leitspirlings als Trophäe.",
"Fenrick: Terribly sorry. He's never liked cartographers. Neither have I, but I have manners.": "Fenrick: Schrecklich leid tut mir das. Er mochte nie Kartografen. Ich auch nicht, aber ich habe Manieren.",
"The daughter from Ashmere": "Die Tochter aus Ashmere",
"Liss Arden, Fenrick's daughter, reports every Marrovel council to Sable.": "Liss Arden, Fenricks Tochter, meldet jede Marrovel-Ratssitzung an Sable.",
"The fading seal": "Das verblassende Siegel",
"Fenrick's bond seal is failing. His Spirling turned on you. Ottilie knew and said nothing.": "Fenricks Bindungssiegel zerfällt. Sein Spirling hat dich angegriffen. Ottilie wusste es und schwieg.",
"Vash: Chief Warden Vash, on holiday. Holidays are when I do my best paperwork.": "Vash: Oberster Hüter Vash, im Urlaub. Im Urlaub mache ich meinen besten Papierkram.",
"Vash: Big day. We're draining the old basin under the sun palace. Civic hygiene.": "Vash: Großer Tag. Wir lassen das alte Becken unter dem Sonnenpalast ab. Öffentliche Hygiene.",
"Vash: Funny what turns up at the bottom of things. Want to watch?": "Vash: Lustig, was am Grund der Dinge so auftaucht. Willst du zusehen?",
"Watch the draining": "Beim Ablassen zusehen",
"Vash: Water forgets nothing. It has that in common with accountants. And me.": "Vash: Wasser vergisst nichts. Das hat es mit Buchhaltern gemeinsam. Und mit mir.",
"The basin drains. At the bottom: sand, one boot, and nothing with your name on it.": "Das Becken läuft leer. Am Grund: Sand, ein Stiefel und nichts mit deinem Namen.",
"Vash: Where is it? There was... I mean. Good. Clean. Very clean. Well done, everybody.": "Vash: Wo ist es? Da war doch... ich meine. Gut. Sauber. Sehr sauber. Gut gemacht, alle.",
"Up on the cemetery wall, Tobs waves his shovel. He charges by the scoop.": "Oben auf der Friedhofsmauer winkt Tobs mit der Schaufel. Er rechnet pro Schaufel ab.",
"At the bottom of the basin lies a Marrovel-sealed urn: the ash from the brooding oven. Veydal sends its regards.": "Am Grund des Beckens liegt eine Urne mit Marrovel-Siegel: die Asche aus dem Brutofen. Veydal lässt grüßen.",
"Vash: Every name in your Ledger is a witness now. Half of them have already sold their statement.": "Vash: Jeder Name in deinem Schuldbuch ist jetzt ein Zeuge. Die Hälfte hat ihre Aussage schon verkauft.",
"Vash: The other half are on their way. Wardens! Arrest this person. Gently. Paperwork hates bruises.": "Vash: Die andere Hälfte ist unterwegs. Hüter! Verhaftet diese Person. Sanft. Papierkram hasst blaue Flecken.",
"The basin under the palace": "Das Becken unter dem Palast",
"Vash moved the brooding oven ash to Solenne and drained the basin in front of witnesses.": "Vash hat die Asche aus dem Brutofen nach Solenne gebracht und das Becken vor Zeugen ablassen lassen.",
"Tobs: Vash's men buried an urn in the palace basin last month. Marrovel seal. Heavy for ash.": "Tobs: Vashs Leute haben letzten Monat eine Urne im Palastbecken vergraben. Marrovel-Siegel. Schwer für Asche.",
"Tobs: I could move it tonight. Five hundred coins. Shovels don't sharpen themselves.": "Tobs: Ich könnte sie heute Nacht umlagern. Fünfhundert Münzen. Schaufeln schärfen sich nicht von selbst.",
"Pay 500 coins": "500 Münzen zahlen",
"What are your rates for silence?": "Was kostet bei dir Schweigen?",
"Tobs: Silence is free. Everybody here is quiet eventually. I just help with the timing.": "Tobs: Schweigen ist gratis. Hier wird jeder irgendwann still. Ich helfe nur beim Timing.",
"Tobs: You asked nicely. I like that. Nobody asks a gravedigger anything nicely.": "Tobs: Du hast nett gefragt. Das mag ich. Einen Totengräber fragt keiner nett.",
"Tobs: Sand's easy to dig. Harder to keep shut.": "Tobs: Sand ist leicht zu graben. Schwer, ihn zuzuhalten.",
"Tobs: Done. The urn sleeps under the old cistern now. And here: you overpaid. I'm a gravedigger, not a thief.": "Tobs: Erledigt. Die Urne schläft jetzt unter der alten Zisterne. Und hier: du hast zu viel bezahlt. Ich bin Totengräber, kein Dieb.",
"Tobs: Done. The urn sleeps under the old cistern now. Don't visit. It gets attached.": "Tobs: Erledigt. Die Urne schläft jetzt unter der alten Zisterne. Nicht besuchen. Sie hängt sonst an dir.",
"Tobs takes your coins, then takes Vash's coins to tell him you paid. Business is steady in Ochrewell.": "Tobs nimmt deine Münzen und dann Vashs Münzen dafür, ihm zu sagen, dass du gezahlt hast. Das Geschäft läuft in Ochrewell.",
"Ottilie: Sit, dear. Solenne is so warm. People drop like flies. Purely the heat, of course.": "Ottilie: Setz dich, Liebes. Solenne ist so warm. Die Leute fallen um wie Fliegen. Natürlich nur die Hitze.",
"Ottilie: Fenrick is fading. The clan needs a steady hand. Yours, at my side. The pact deeds, too.": "Ottilie: Fenrick verblasst. Der Clan braucht eine ruhige Hand. Deine, an meiner Seite. Die Pakturkunden dazu.",
"Ottilie: Just sign. The wax is still warm. I warmed it myself.": "Ottilie: Unterschreib einfach. Das Wachs ist noch warm. Ich habe es selbst gewärmt.",
"Sign": "Unterschreiben",
"Let Marlo look at the wax": "Marlo das Wachs ansehen lassen",
"Marlo sniffs the seal. Then he sniffs it again, the way he sniffs a bad tooth.": "Marlo riecht am Siegel. Dann noch einmal, so wie er an einem faulen Zahn riecht.",
"Marlo: Sleepwort in the wax. Lick the seal and you nap for a week. Or for good. Depends on the week.": "Marlo: Schlafkraut im Wachs. Leck am Siegel und du schläfst eine Woche. Oder für immer. Hängt von der Woche ab.",
"Marlo: Fenrick buys his wax from the same shop. I'd ask him about his, too.": "Marlo: Fenrick kauft sein Wachs im selben Laden. Ich würde ihn auch nach seinem fragen.",
"Fenrick: Ah, my favourite scapegoat! No, no, I mean that warmly.": "Fenrick: Ah, mein liebster Sündenbock! Nein, nein, das meine ich herzlich.",
"Fenrick: Ottilie wants my chair. Let's give it to you instead. A son in all but blood and paperwork.": "Fenrick: Ottilie will meinen Stuhl. Geben wir ihn lieber dir. Ein Sohn, nur ohne Blut und Papiere.",
"Fenrick: The pact deeds, the clan, the portrait wall. Sign here. Mind the wax, it's my own recipe.": "Fenrick: Die Pakturkunden, der Clan, die Porträtwand. Unterschreib hier. Vorsicht mit dem Wachs, eigenes Rezept.",
"Play them against each other": "Sie gegeneinander ausspielen",
"Fenrick: The sun's set on Solenne, they say. Then it rises again, the show-off.": "Fenrick: Die Sonne über Solenne ist untergegangen, sagt man. Dann geht sie wieder auf, die Angeberin.",
"You tell Fenrick about Ottilie's offer. Then you tell Ottilie about Fenrick's. Same wax, same smile.": "Du erzählst Fenrick von Ottilies Angebot. Dann Ottilie von Fenricks. Gleiches Wachs, gleiches Lächeln.",
"By sunset they are not speaking. By midnight they are writing to their lawyers. By morning the deeds are in your bag.": "Bei Sonnenuntergang reden sie nicht mehr. Um Mitternacht schreiben sie ihren Anwälten. Am Morgen liegen die Urkunden in deiner Tasche.",
"Two offers, one sleepwort. At least they agree on something.": "Zwei Angebote, ein Schlafkraut. Wenigstens sind sie sich bei etwas einig.",
"You hand the contract back unsigned. The wax is green. Wax is never green.": "Du gibst den Vertrag ungezeichnet zurück. Das Wachs ist grün. Wachs ist nie grün.",
"Ottilie: Clever. I do so hate clever. It always lives longer than planned.": "Ottilie: Klug. Ich hasse klug. Klug lebt immer länger als geplant.",
"You seal the contract the old way, with a lick of wax. The room tilts gently into the sand.": "Du siegelst den Vertrag nach alter Art, mit etwas Wachs an der Zunge. Der Raum kippt sanft in den Sand.",
"Ottilie: Sleep, dear. The clan will be in such good hands. Mine.": "Ottilie: Schlaf, Liebes. Der Clan ist in so guten Händen. In meinen.",
"You wake behind the bazaar, coins gone, guards circling. The heat, of course.": "Du wachst hinter dem Basar auf, Münzen weg, Wachen ringsum. Die Hitze, natürlich.",
"You blow on the seal instead of licking it. Fenrick watches the green smoke curl and sighs.": "Du pustest auf das Siegel, statt es abzulecken. Fenrick sieht dem grünen Rauch nach und seufzt.",
"Fenrick: Ottilie's recipe. I stole it. Forty years of marriage, and that's what we share.": "Fenrick: Ottilies Rezept. Ich habe es geklaut. Vierzig Jahre Ehe, und das ist es, was wir teilen.",
"The wax tastes of honey and bad decisions. Then of nothing at all.": "Das Wachs schmeckt nach Honig und schlechten Entscheidungen. Dann nach gar nichts mehr.",
"Fenrick: No hard feelings! I'll have your portrait painted. Lying down. Very restful.": "Fenrick: Nichts für ungut! Ich lasse dein Porträt malen. Liegend. Sehr erholsam.",
"Two thrones, one sleepwort": "Zwei Throne, ein Schlafkraut",
"Ottilie and Fenrick each offered you the clan seat. Both seals carried the same sleepwort.": "Ottilie und Fenrick boten dir beide den Clansitz an. Beide Siegel trugen dasselbe Schlafkraut.",
"The pact deeds": "Die Pakturkunden",
"You played the Kaels against each other and walked off with the Rift pact deeds. Neither will forgive it.": "Du hast die Kaels gegeneinander ausgespielt und bist mit den Pakturkunden gegangen. Keiner verzeiht dir das.",
"Wren: Surprise. I took the sand road. Ottilie wants the Crooked Kettle as an egg store. Contraband eggs.": "Wren: Überraschung. Ich bin die Sandstraße runtergekommen. Ottilie will den Schiefen Kessel als Eierlager. Schmuggeleier.",
"Wren: She says you'll talk me round. Will you?": "Wren: Sie sagt, du redest mich um. Tust du das?",
"Do it for the clan": "Tu es für den Clan",
"I'm with you, Wren": "Ich stehe zu dir, Wren",
"Wren: Right. Then I'll leave you the key. And the cellar. Mind the cellar.": "Wren: Gut. Dann lasse ich dir den Schlüssel da. Und den Keller. Pass auf den Keller auf.",
"Wren: There's a Ruskweber spy down there. Been there since spring. He's learned to knit. Feed him Tuesdays.": "Wren: Da unten sitzt ein Ruskweber-Spitzel. Seit dem Frühling. Er hat Stricken gelernt. Dienstags füttern.",
"Wren: Good answer. Wrong for your health, but good.": "Wren: Gute Antwort. Falsch für deine Gesundheit, aber gut.",
"Wren: I tidied the cellar. There's a Ruskweber spy down there since spring. He knits now. Lovely scarves.": "Wren: Ich habe den Keller aufgeräumt. Da unten sitzt seit dem Frühling ein Ruskweber-Spitzel. Er strickt jetzt. Schöne Schals.",
"Wren: Ottilie won't like this. Ottilie doesn't like weather either, and it still happens.": "Wren: Ottilie wird das nicht mögen. Ottilie mag auch kein Wetter, und es passiert trotzdem.",
"Wren: Rooms by the night, secrets by the hour. In Solenne, the hour is shorter.": "Wren: Zimmer pro Nacht, Geheimnisse pro Stunde. In Solenne ist die Stunde kürzer.",
"Wren looks through you, as if you were a guest who never paid.": "Wren sieht durch dich hindurch, als wärst du ein Gast, der nie bezahlt hat.",
"Mother Grell: Solenne. Our second seat. Here the sand keeps our secrets. Usually.": "Mother Grell: Solenne. Unser zweiter Sitz. Hier hütet der Sand unsere Geheimnisse. Meistens.",
"Mother Grell: You sold my breeder to the Marrovels. They paid you in compliments. I pay in consequences.": "Mother Grell: Du hast meinen Züchter an die Marrovels verkauft. Die haben dich mit Komplimenten bezahlt. Ich bezahle mit Folgen.",
"Mother Grell: There's a young man asking for Pip. I gave him directions. And a packed lunch.": "Mother Grell: Ein junger Mann fragt nach Pip. Ich habe ihm den Weg erklärt. Und ihm ein Pausenbrot gemacht.",
"Mother Grell: You kept my secret. I keep accounts. Here's a free entry.": "Mother Grell: Du hast mein Geheimnis bewahrt. Ich führe Buch. Hier ein Gratiseintrag.",
"Mother Grell: Kerr Haldane is hunting Pip. He has eyewitness crystals. And Ottilie's handwriting, if you know where to look.": "Mother Grell: Kerr Haldane jagt Pip. Er hat Augenzeugenkristalle. Und Ottilies Handschrift, wenn man weiß, wo man sucht.",
"Mother Grell: Don't thank me. Thanks are for people who expect to live long.": "Mother Grell: Bedank dich nicht. Dank ist für Leute, die lange leben wollen.",
"Sable: You! Alive! I'm thrilled. Genuinely. I bet against it.": "Sable: Du! Am Leben! Ich bin begeistert. Ehrlich. Ich hatte dagegen gewettet.",
"Sable: Let me make it up to you. The dune pass to the Sun Rift is clear tonight. My word on it.": "Sable: Lass es mich wiedergutmachen. Der Dünenpass zum Sonnenriss ist heute Nacht frei. Mein Wort darauf.",
"Your word is worth sand": "Dein Wort ist Sand wert",
"Sable: Trust is like sand. It's everywhere and you can't hold any of it.": "Sable: Vertrauen ist wie Sand. Es ist überall und man kann nichts davon festhalten.",
"The dune pass is not clear. It is full of Ruskweber hands holding Sable's IOUs.": "Der Dünenpass ist nicht frei. Er ist voller Ruskweber-Handlanger mit Sables Schuldscheinen.",
"The dune pass really is clear. Sable is as surprised as you are. He looks almost hurt.": "Der Dünenpass ist wirklich frei. Sable ist so überrascht wie du. Er wirkt fast gekränkt.",
"The pass is clear, and someone left a revival leaf on the marker stone. Signed: 'Interest. S.'": "Der Pass ist frei, und auf dem Grenzstein liegt ein Lebensblatt. Unterschrift: 'Zinsen. S.'",
"Pip: There's a man in town with my face in a crystal. The night of the Ashmere run.": "Pip: In der Stadt ist ein Mann mit meinem Gesicht in einem Kristall. Die Nacht der Flucht durch Ashmere.",
"Pip: His father guarded a Rift. My duel knocked his Spirling into the Hush. He went in after it. He never came out.": "Pip: Sein Vater hat einen Riss bewacht. Mein Duell hat seinen Spirling in die Stille gestoßen. Er ging hinterher. Er kam nie raus.",
"Pip: I forgot him. He didn't forget me. That's how it works, isn't it?": "Pip: Ich hatte ihn vergessen. Er mich nicht. So läuft das, oder?",
"Pip won't look at you. Somewhere, a Kael learns what a Kael is for.": "Pip sieht dich nicht an. Irgendwo lernt eine Kael, wofür eine Kael da ist.",
"Pip: You stood in front of me. Nobody in my family ever stood in front of me. Only behind.": "Pip: Du hast dich vor mich gestellt. Niemand aus meiner Familie hat sich je vor mich gestellt. Nur hinter mich.",
"Kerr Haldane: Kerr. My father kept the Ashmere Rift. Then a Kael girl played games at its edge.": "Kerr Haldane: Kerr. Mein Vater hat den Ashmere-Riss bewacht. Dann hat ein Kael-Mädchen an seinem Rand gespielt.",
"Kerr Haldane: I want Pip in front of the Wardens. Not Vash's Wardens. Honest ones. I'll find some.": "Kerr Haldane: Ich will Pip vor den Hütern. Nicht Vashs Hütern. Ehrlichen. Ich finde schon welche.",
"Kerr Haldane: You can step aside. Or you can be the second name in my crystal.": "Kerr Haldane: Du kannst zur Seite treten. Oder der zweite Name in meinem Kristall werden.",
"Take Pip": "Nimm Pip",
"Over my Spirlings": "Nur über meine Spirlinge",
"Ottilie wrote the note": "Ottilie hat den Zettel geschrieben",
"Kerr Haldane: Thank you. Strange. I thought justice would feel bigger.": "Kerr Haldane: Danke. Seltsam. Ich dachte, Gerechtigkeit fühlt sich größer an.",
"You tell him about the note that sent Pip to the duel. Same ink as Ottilie's letters.": "Du erzählst ihm von dem Zettel, der Pip zum Duell geschickt hat. Dieselbe Tinte wie Ottilies Briefe.",
"Kerr Haldane: So the girl was the arrow. I want the archer.": "Kerr Haldane: Das Mädchen war also der Pfeil. Ich will den Bogenschützen.",
"Kerr Haldane: Crystals remember everything. Unlike families.": "Kerr Haldane: Kristalle erinnern sich an alles. Anders als Familien.",
"Kerr Haldane: Fine. Keep her. But I keep the crystal. One day someone honest will want to see it.": "Kerr Haldane: Gut. Behalt sie. Aber ich behalte den Kristall. Eines Tages will ihn jemand Ehrliches sehen.",
"Kerr Haldane: Go home. Think about who you're bleeding for.": "Kerr Haldane: Geh nach Hause. Denk darüber nach, für wen du dich verausgabst.",
"The Marrovel guards leave you in the shade. Courtesy of the house.": "Die Marrovel-Wachen lassen dich im Schatten liegen. Mit Empfehlung des Hauses.",
"The Wardens take your statement, your coins and your afternoon.": "Die Hüter nehmen deine Aussage, deine Münzen und deinen Nachmittag.",
"Ottilie: The sun is mended. How lovely. Come to the palace, dear. Family business.": "Ottilie: Die Sonne ist geflickt. Wie hübsch. Komm in den Palast, Liebes. Familiensache.",
"Ottilie: We'll speak again. We always do. Usually at funerals.": "Ottilie: Wir sprechen uns wieder. Das tun wir immer. Meistens auf Beerdigungen.",
"Ottilie raises a glass. Fenrick raises a glass. Each watches the other's glass.": "Ottilie hebt ein Glas. Fenrick hebt ein Glas. Jeder beobachtet das Glas des anderen.",
"Ottilie: To family. And to the one who did our dirty work so beautifully.": "Ottilie: Auf die Familie. Und auf den, der unsere Drecksarbeit so schön erledigt hat.",
"Fenrick: The deeds. Where are the pact deeds?": "Fenrick: Die Urkunden. Wo sind die Pakturkunden?",
"Ottilie: You had them. ...No. Look at the cartographer. Look at that terrible, honest face.": "Ottilie: Du hattest sie. ...Nein. Sieh dir den Kartografen an. Dieses schreckliche, ehrliche Gesicht.",
"Ottilie lays the pact deeds on the table, between the bread and the knives.": "Ottilie legt die Pakturkunden auf den Tisch, zwischen Brot und Messer.",
"Ottilie: Whoever holds these holds the Rifts. Tonight, that is me. Tomorrow, we'll see who's breathing.": "Ottilie: Wer die hält, hält die Risse. Heute Nacht bin das ich. Morgen sehen wir, wer noch atmet.",
"The doors open. Mother Grell walks in with Brannoc at her shoulder, wearing Ruskweber grey.": "Die Türen gehen auf. Mother Grell kommt herein, Brannoc an ihrer Schulter, in Ruskweber-Grau.",
"Brannoc: Evening, Mother. Father. I brought my new family. They're punctual.": "Brannoc: Abend, Mutter. Vater. Ich habe meine neue Familie mitgebracht. Die sind pünktlich.",
"Behind them comes Kerr Haldane, a crystal in his fist, looking only at Ottilie.": "Hinter ihnen kommt Kerr Haldane, einen Kristall in der Faust, und sieht nur Ottilie an.",
"Kerr Haldane: You wrote a note to a child. I came to read it back to you.": "Kerr Haldane: Du hast einem Kind einen Zettel geschrieben. Ich bin gekommen, um ihn dir vorzulesen.",
"Marlo leans in the doorway with his bag. Nobody invited him. Doctors are never invited, only needed.": "Marlo lehnt mit seiner Tasche im Türrahmen. Niemand hat ihn eingeladen. Ärzte werden nie eingeladen, nur gebraucht.",
"There is an empty chair at the end of the table. Nobody mentions whose it was.": "Am Ende des Tisches steht ein leerer Stuhl. Niemand sagt, wessen Platz das war.",
"Every eye in the hall turns to you. The fixer. Competent, needed, and never family.": "Jedes Auge im Saal richtet sich auf dich. Den Fixer. Fähig, unverzichtbar und nie Familie.",
"Ottilie: Choose, dear. Choose carefully. Everyone here has a long memory and a short temper.": "Ottilie: Wähle, Liebes. Wähle sorgfältig. Hier hat jeder ein langes Gedächtnis und eine kurze Geduld.",
"Burn the pact deeds": "Die Pakturkunden verbrennen",
"Give them to the Warden guild": "Sie der Hütergilde geben",
"Keep them. Both clans owe me now": "Behalten. Jetzt schulden mir beide Clans",
"You hold the deeds to the candle. Old paper burns fast. Old families burn slower.": "Du hältst die Urkunden in die Kerze. Altes Papier brennt schnell. Alte Familien brennen langsamer.",
"Ottilie: Forty years of debts. Gone. Do you know how many people will stop fearing us?": "Ottilie: Vierzig Jahre Schulden. Weg. Weißt du, wie viele Leute jetzt keine Angst mehr vor uns haben?",
"Mother Grell: Ha! I've never liked you more. Run before I change my mind.": "Mother Grell: Ha! Ich mochte dich nie mehr. Lauf, bevor ich es mir anders überlege.",
"You hand the deeds to the Warden guild clerk. Not to Vash. Vash watches them go like a man watching his lunch leave.": "Du gibst die Urkunden dem Schreiber der Hütergilde. Nicht Vash. Vash sieht ihnen nach wie ein Mann, dem man das Mittagessen wegträgt.",
"Vash: The guild. How... procedural. I'll need a moment. And a new career.": "Vash: Die Gilde. Wie... ordnungsgemäß. Ich brauche einen Moment. Und eine neue Laufbahn.",
"Fenrick: Paperwork. Beaten by paperwork. Paint that, someone.": "Fenrick: Papierkram. Geschlagen von Papierkram. Malt das, irgendwer.",
"You fold the deeds into your coat. The hall goes very quiet. Everyone does the same sum.": "Du faltest die Urkunden in deinen Mantel. Der Saal wird sehr still. Alle rechnen dieselbe Summe.",
"Ottilie: Well. You've betrayed us both. I'm almost proud. Sleep with the lamp on.": "Ottilie: Nun. Du hast uns beide verraten. Ich bin fast stolz. Schlaf mit Licht.",
"Mother Grell: Two clans and one fixer holding the leash. That never ends well. For the fixer.": "Mother Grell: Zwei Clans und ein Fixer, der die Leine hält. Das geht nie gut aus. Für den Fixer.",
"Wren waits outside with two cups of tea, one of them for you. That's how you know.": "Wren wartet draußen mit zwei Tassen Tee, eine davon für dich. Daran merkst du es.",
"Outside the palace nobody waits. The sand has already covered your footprints.": "Vor dem Palast wartet niemand. Der Sand hat deine Spuren schon zugedeckt.",
"The fixer's crown": "Die Krone des Fixers",
"You kept the pact deeds. Both clans owe you, and both have started counting.": "Du hast die Pakturkunden behalten. Beide Clans schulden dir etwas, und beide haben angefangen zu zählen.",
"Far behind you, in Solenne, the clans are counting their debts. Some things even the Echo can't quiet.": "Weit hinter dir, in Solenne, zählen die Clans ihre Schulden. Manches kann nicht einmal der Nachhall zum Schweigen bringen.",
"Somewhere in Solenne, ash drifts over a palace where nobody owes anybody anything. It won't last. It's nice while it does.": "Irgendwo in Solenne weht Asche über einen Palast, in dem niemand mehr jemandem etwas schuldet. Das hält nicht. Aber schön, solange es hält.",
"Somewhere in Solenne, a guild clerk is reading forty years of crimes in alphabetical order. He has asked for an assistant.": "Irgendwo in Solenne liest ein Gildenschreiber vierzig Jahre Verbrechen in alphabetischer Reihenfolge. Er hat um einen Gehilfen gebeten.",
"Somewhere in Solenne, two clans are sharpening their pens. Your name is on both lists. Trust no one. Least of all the one in your mirror.": "Irgendwo in Solenne spitzen zwei Clans ihre Federn. Dein Name steht auf beiden Listen. Trau niemandem. Am wenigsten dem im Spiegel.",
"The Sun Palace at dusk. One long table, too many knives, and every chair placed with intent.": "Der Sonnenpalast in der Dämmerung. Ein langer Tisch, zu viele Messer, und jeder Stuhl mit Absicht gestellt.",
"Far to the north the sky over the Wide Rift tears a little wider. Nobody at the table notices. They're busy.": "Weit im Norden reißt der Himmel über dem Weiten Riss ein Stück weiter auf. Am Tisch merkt es keiner. Sie sind beschäftigt.",
"Chief Warden's Guard": "Wache des Obersten Hüters",
"Marrovel Guard": "Marrovel-Wache",
"Kerr Haldane": "Kerr Haldane",
}
T["Mirela: People ask if I get lonely. I tell them the Echo talks back. Then they stop asking. Works every time."] = "Mirela: Die Leute fragen, ob ich einsam bin. Ich sage, der Nachhall antwortet. Dann fragen sie nicht mehr. Klappt jedes Mal."
